function cdfLookup(z,knots,probs){
  if(!Array.isArray(knots)||!Array.isArray(probs)||knots.length!==probs.length)return null;
  const n=knots.length;
  if(!Number.isFinite(z))return null;
  // Discrete scales repeat one quantile value across a band of probabilities. A score on
  // such a tie gets the midrank of the band, not whichever end the rounding of z selects.
  for(let i=0;i<n;){
    let j=i;while(j+1<n&&knots[j+1]===knots[i])j++;
    if(j>i){
      const gapLo=i>0?knots[i]-knots[i-1]:Infinity,gapHi=j<n-1?knots[j+1]-knots[j]:Infinity;
      const tol=Math.min(0.012,gapLo*0.45,gapHi*0.45);
      if((i===0&&z<=knots[0]+tol)||(j===n-1&&z>=knots[n-1]-tol)||Math.abs(z-knots[i])<=tol)return (probs[i]+probs[j])/2;
    }
    i=j+1;
  }
  if(z<=knots[0])return probs[0];
  if(z>=knots[n-1])return probs[n-1];
  let lo=0,hi=n-1;
  while(hi-lo>1){const mid=(lo+hi)>>1;if(knots[mid]<=z)lo=mid;else hi=mid;}
  const span=knots[hi]-knots[lo];
  if(span<=1e-9)return probs[hi];
  return probs[lo]+((z-knots[lo])/span)*(probs[hi]-probs[lo]);
}
function csemAtScore(score100,knots){
  if(!Array.isArray(knots)||knots.length!==11)return null;
  const n=Number(score100),s=Math.max(0,Math.min(100,Number.isFinite(n)?n:50));
  const pos=s/10,idx=Math.min(9,Math.floor(pos)),frac=pos-idx;
  return knots[idx]+frac*(knots[idx+1]-knots[idx]);
}
const api={data,cdfLookup(z,knots){return cdfLookup(z,knots,data.quantileProbs);},csemAtScore};
